class Solution:
    def maxAlternatingSum(self, nums: List[int]) -> int:
        def dfs(i, cnt):
            if i == len(nums):
                return 0
            sign = 1 if cnt % 2 == 0 else -1
            return max(dfs(i + 1, cnt), sign * nums[i] + dfs(i + 1, cnt + 1))

        return dfs(0, 0)

