class Solution {
public:
    long long maxAlternatingSum(vector<int>& nums) {
        int n = nums.size();
        function<long long(int, int)> dfs = [&](int i, int cnt) -> long long {
            if (i == n) return 0;
            long long sign = (cnt % 2 == 0) ? 1 : -1;
            return max(dfs(i + 1, cnt), sign * nums[i] + dfs(i + 1, cnt + 1));
        };
        return dfs(0, 0);
    }
};

