class Solution {
    public long maxAlternatingSum(int[] nums) {
        return dfs(nums, 0, 0);
    }

    private long dfs(int[] nums, int i, int cnt) {
        if (i == nums.length) return 0;
        long sign = (cnt % 2 == 0) ? 1 : -1;
        return Math.max(dfs(nums, i + 1, cnt), sign * nums[i] + dfs(nums, i + 1, cnt + 1));
    }
}

