class Solution {
public:
    long long maxAlternatingSum(vector<int>& nums) {
        long long ans = max(nums[0], 0);
        for (int i = 1; i < (int)nums.size(); ++i)
            ans += max(0, nums[i] - nums[i - 1]);
        return ans;
    }
};

